1	//! `MessageTranslator` — Anthropic SSE events → `ModelEvent` stream.
2	
3	use std::collections::HashMap;
4	
5	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
6	
7	use crate::error::map_error_type;
8	use crate::provider_data::{AnthropicData, ThinkingBlock};
9	use crate::sse::{
10	    AnthropicEvent, ContentBlockDelta, ContentBlockHead, MessageDeltaUsage, MessageStartUsage,
11	};
12	use crate::translate::response_format::SYNTHESIZED_TOOL_NAME;
13	
14	#[derive(Debug)]
15	enum BlockState {
16	    Text {
17	        bytes: u64,
18	    },
19	    Thinking {
20	        text: String,
21	        signature: String,
22	    },
23	    RedactedThinking {
24	        data: String,
25	    },
26	    ToolUse {
27	        call_id: String,
28	        name: String,
29	        name_emitted: bool,
30	    },
31	}
32	
33	/// State machine for one streaming response.
34	///
35	/// `synthesizing_output: true` means a `ResponseFormat::JsonSchema`/`JsonObject`
36	/// request was sent. When the synthesized tool's content block starts, its
37	/// `input_json_delta` events are remapped to `TokenDelta`s and the
38	/// `stop_reason: "tool_use"` is rewritten to `Stop` if it was the only tool fired.
39	pub(crate) struct MessageTranslator {
40	    blocks: HashMap<u32, BlockState>,
41	    last_input_tokens: u32,
42	    last_cached_input_tokens: Option<u32>,
43	    stop_reason: Option<String>,
44	    synthesizing_output: bool,
45	    synthesized_tool_index: Option<u32>,
46	    other_tool_fired: bool,
47	    terminal_emitted: bool,
48	    /// The stream has emitted a `block` part of this response.
49	    block_emitted: bool,
50	    /// Position records that wait for the first `block` part.
51	    waiting_positions: Vec<ModelEvent>,
52	}
53	
54	impl MessageTranslator {
55	    pub(crate) fn new(synthesizing_output: bool) -> Self {
56	        Self {
57	            blocks: HashMap::new(),
58	            last_input_tokens: 0,
59	            last_cached_input_tokens: None,
60	            stop_reason: None,
61	            synthesizing_output,
62	            synthesized_tool_index: None,
63	            other_tool_fired: false,
64	            terminal_emitted: false,
65	            block_emitted: false,
66	            waiting_positions: Vec::new(),
67	        }
68	    }
69	
70	    /// Consume one event. Returns the emitted ModelEvents (most calls
71	    /// emit zero or one; `message_delta` carrying both stop_reason and
72	    /// usage emits one Usage followed by Finish on `message_stop`). A
73	    /// terminal event (`Finish` or an `Err`) is emitted at most once per
74	    /// stream, and a later `message_delta`'s `Usage` is suppressed once one
75	    /// has been emitted. Content deltas are deliberately *not* guarded: a
76	    /// malformed stream that keeps sending `content_block_delta` after
77	    /// `message_stop` would still yield them. A clean end-of-stream flush of
78	    /// a buffered stop reason with no terminal event yet is handled
79	    /// separately by `finish()`.
80	    pub(crate) fn consume(
81	        &mut self,
82	        event: AnthropicEvent,
83	    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
84	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
85	        match event {
86	            AnthropicEvent::MessageStart { message } => {
87	                let MessageStartUsage {
88	                    input_tokens,
89	                    cache_read_input_tokens,
90	                    ..
91	                } = message.usage;
92	                self.last_input_tokens = input_tokens;
93	                self.last_cached_input_tokens = cache_read_input_tokens;
94	                out.push(Ok(ModelEvent::Usage {
95	                    input_tokens,
96	                    output_tokens: 0,
97	                    cached_input_tokens: cache_read_input_tokens,
98	                    reasoning_tokens: None,
99	                }));
100	            }
101	            AnthropicEvent::ContentBlockStart {
102	                index,
103	                content_block,
104	            } => match content_block {
105	                ContentBlockHead::Text => {
106	                    self.blocks.insert(index, BlockState::Text { bytes: 0 });
107	                }
108	                ContentBlockHead::Thinking {
109	                    thinking,
110	                    signature,
111	                } => {
112	                    self.blocks.insert(
113	                        index,
114	                        BlockState::Thinking {
115	                            text: thinking,
116	                            signature,
117	                        },
118	                    );
119	                }
120	                ContentBlockHead::RedactedThinking { data } => {
121	                    self.blocks
122	                        .insert(index, BlockState::RedactedThinking { data });
123	                }
124	                ContentBlockHead::ToolUse { id, name, .. } => {
125	                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
126	                        self.synthesized_tool_index = Some(index);
127	                    } else {
128	                        self.other_tool_fired = true;
129	                    }
130	                    self.blocks.insert(
131	                        index,
132	                        BlockState::ToolUse {
133	                            call_id: id,
134	                            name,
135	                            name_emitted: false,
136	                        },
137	                    );
138	                }
139	            },
140	            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
141	                ContentBlockDelta::TextDelta { text } => {
142	                    if let Some(BlockState::Text { bytes }) = self.blocks.get_mut(&index) {
143	                        *bytes = bytes.saturating_add(text.len() as u64);
144	                    } else {
145	                        tracing::debug!(
146	                            target: "paigasus::anthropic::stream",
147	                            index,
148	                            "text_delta for a block that is not an open text block",
149	                        );
150	                    }
151	                    out.push(Ok(ModelEvent::TokenDelta { text }));
152	                }
153	                ContentBlockDelta::ThinkingDelta { thinking } => {
154	                    if let Some(BlockState::Thinking { text, .. }) = self.blocks.get_mut(&index) {
155	                        text.push_str(&thinking);
156	                    }
157	                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
158	                }
159	                ContentBlockDelta::SignatureDelta { signature } => {
160	                    if let Some(BlockState::Thinking {
161	                        signature: joined, ..
162	                    }) = self.blocks.get_mut(&index)
163	                    {
164	                        joined.push_str(&signature);
165	                    } else {
166	                        tracing::debug!(
167	                            target: "paigasus::anthropic::stream",
168	                            index,
169	                            "signature_delta for a block that is not open; dropped",
170	                        );
171	                    }
172	                }
173	                ContentBlockDelta::InputJsonDelta { partial_json } => {
174	                    let is_synth = Some(index) == self.synthesized_tool_index;
175	                    if is_synth {
176	                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
177	                    } else if let Some(BlockState::ToolUse {
178	                        call_id,
179	                        name,
180	                        name_emitted,
181	                    }) = self.blocks.get_mut(&index)
182	                    {
183	                        let (emit_name, call_id_out) = if *name_emitted {
184	                            (None, call_id.clone())
185	                        } else {
186	                            *name_emitted = true;
187	                            (Some(name.clone()), call_id.clone())
188	                        };
189	                        out.push(Ok(ModelEvent::ToolCallDelta {
190	                            call_id: call_id_out,
191	                            name: emit_name,
192	                            args_delta: partial_json,
193	                        }));
194	                    } else {
195	                        // Protocol violation: input_json_delta only ever
196	                        // applies to a tool_use content block. Surface it
197	                        // rather than silently dropping (which would mask
198	                        // a malformed upstream stream).
199	                        return Err(ModelError::Transport(format!(
200	                            "anthropic stream: input_json_delta at index {index} \
201	                             has no preceding tool_use content_block_start"
202	                        )));
203	                    }
204	                }
205	            },
206	            AnthropicEvent::ContentBlockStop { index } => {
207	                self.stop_block(index, &mut out);
208	            }
209	            AnthropicEvent::MessageDelta { delta, usage } => {
210	                // A `message_delta` after the terminal event is a protocol
211	                // violation (e.g. a second `message_delta` re-arming
212	                // `stop_reason` post-`message_stop`, see
213	                // `second_message_delta_after_message_stop_does_not_double_finish`).
214	                // Emitting its `Usage` would put an event after `Finish`,
215	                // which the core contract forbids.
216	                if !self.terminal_emitted {
217	                    if let Some(MessageDeltaUsage { output_tokens }) = usage {
218	                        out.push(Ok(ModelEvent::Usage {
219	                            input_tokens: self.last_input_tokens,
220	                            output_tokens,
221	                            cached_input_tokens: self.last_cached_input_tokens,
222	                            reasoning_tokens: None,
223	                        }));
224	                    }
225	                }
226	                if let Some(reason) = delta.stop_reason {
227	                    self.stop_reason = Some(reason);
228	                }
229	            }
230	            AnthropicEvent::MessageStop => {
231	                if let Some(reason) = self.stop_reason.take() {
232	                    if !self.terminal_emitted {
233	                        self.terminal_emitted = true;
234	                        out.push(self.finish_or_error(&reason));
235	                    }
236	                }
237	            }
238	            AnthropicEvent::Ping => {}
239	            AnthropicEvent::Error { error } => {
240	                return Err(map_error_type(None, &error.ty, &error.message, None));
241	            }
242	        }
243	        Ok(out)
244	    }
245	
246	    /// Close the block at `index`: keep a valid thinking block and record the
247	    /// positions of each text block and each `tool_use` block.
248	    fn stop_block(&mut self, index: u32, out: &mut Vec<Result<ModelEvent, ModelError>>) {
249	        // No event can follow `Finish`, so a block stop after the terminal
250	        // event gives no provider data.
251	        if self.terminal_emitted {
252	            tracing::debug!(
253	                target: "paigasus::anthropic::stream",
254	                index,
255	                "content_block_stop after the terminal event",
256	            );
257	            return;
258	        }
259	        let Some(state) = self.blocks.remove(&index) else {
260	            tracing::debug!(
261	                target: "paigasus::anthropic::stream",
262	                index,
263	                "content_block_stop for a block that is not open",
264	            );
265	            return;
266	        };
267	        match state {
268	            BlockState::Thinking { text, signature } => self.keep_block(
269	                index,
270	                "thinking",
271	                ThinkingBlock::Thinking {
272	                    thinking: text,
273	                    signature,
274	                },
275	                out,
276	            ),
277	            BlockState::RedactedThinking { data } => self.keep_block(
278	                index,
279	                "redacted_thinking",
280	                ThinkingBlock::RedactedThinking { data },
281	                out,
282	            ),
283	            BlockState::Text { bytes } => self.position(
284	                AnthropicData::Text {
285	                    index,
286	                    bytes: Some(bytes),
287	                }
288	                .into_event(None),
289	                out,
290	            ),
291	            BlockState::ToolUse {
292	                call_id,
293	                name_emitted,
294	                ..
295	            } => {
296	                if name_emitted && Some(index) != self.synthesized_tool_index {
297	                    self.position(
298	                        AnthropicData::ToolUse { index }.into_event(Some(call_id)),
299	                        out,
300	                    );
301	                }
302	            }
303	        }
304	    }
305	
306	    /// Emit a valid thinking block, then every position that waits for it.
307	    fn keep_block(
308	        &mut self,
309	        index: u32,
310	        kind: &str,
311	        block: ThinkingBlock,
312	        out: &mut Vec<Result<ModelEvent, ModelError>>,
313	    ) {
314	        if !block.is_valid() {
315	            tracing::debug!(
316	                target: "paigasus::anthropic::stream",
317	                index,
318	                kind,
319	                "thinking block without signature or data is not kept",
320	            );
321	            return;
322	        }
323	        out.push(Ok(AnthropicData::Block { index, block }.into_event(None)));
324	        if !self.block_emitted {
325	            self.block_emitted = true;
326	            out.extend(self.waiting_positions.drain(..).map(Ok));
327	        }
328	    }
329	
330	    /// Emit a position record now, or hold it until the first `block` part.
331	    fn position(&mut self, event: ModelEvent, out: &mut Vec<Result<ModelEvent, ModelError>>) {
332	        if self.block_emitted {
333	            out.push(Ok(event));
334	        } else {
335	            self.waiting_positions.push(event);
336	        }
337	    }
338	
339	    /// Flush a stop reason buffered from `message_delta` when the response
340	    /// body ends cleanly before `message_stop` arrived.
341	    ///
342	    /// Returns `None` when a terminal event was already emitted — the
343	    /// well-formed path, where `message_stop` drained the buffer — or when no
344	    /// stop reason was ever observed. A stream that ended *before*
345	    /// `message_delta` is never reported as a clean `Stop`; one that ended
346	    /// *after* it is, because `message_delta`'s `stop_reason` is the model's
347	    /// own authoritative decision and `message_stop` is only a frame
348	    /// terminator.
349	    ///
350	    /// `terminal_emitted` — not `stop_reason` being `Some` — is the guard.
351	    /// A second `message_delta` can re-arm the buffer after `message_stop`
352	    /// already emitted, and that must not produce a second terminal event.
353	    ///
354	    /// **Clean-EOF path only.** Never call this on the cancellation or
355	    /// transport-error paths — see `model.rs`.
356	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
357	        if self.terminal_emitted {
358	            return None;
359	        }
360	        let reason = self.stop_reason.take()?;
361	        self.terminal_emitted = true;
362	        tracing::warn!(
363	            target: "paigasus::anthropic::stream",
364	            stop_reason = %reason,
365	            "stream body ended without message_stop; flushing buffered stop reason",
366	        );
367	        Some(self.finish_or_error(&reason))
368	    }
369	
370	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
371	        match reason {
372	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
373	                reason: FinishReason::Stop,
374	            }),
375	            "max_tokens" => Ok(ModelEvent::Finish {
376	                reason: FinishReason::Length,
377	            }),
378	            "tool_use" => {
379	                if self.synthesizing_output && !self.other_tool_fired {
380	                    Ok(ModelEvent::Finish {
381	                        reason: FinishReason::Stop,
382	                    })
383	                } else if self.synthesizing_output && self.other_tool_fired {
384	                    Err(ModelError::Other(anyhow::anyhow!(
385	                        "structured output: model fired both a real tool and the synthesized output tool"
386	                    )))
387	                } else {
388	                    Ok(ModelEvent::Finish {
389	                        reason: FinishReason::ToolCalls,
390	                    })
391	                }
392	            }
393	            "refusal" => Err(ModelError::Refused {
394	                reason: "model refused".to_owned(),
395	            }),
396	            other => Ok(ModelEvent::Finish {
397	                reason: FinishReason::Other(other.to_owned()),
398	            }),
399	        }
400	    }
401	}
