    let mut items = Vec::new();
    if !text.is_empty() || !reasoning.is_empty() || !provider_data.is_empty() {
        let mut content = Vec::new();
        if !reasoning.is_empty() {
            content.push(crate::ContentPart::Reasoning { text: reasoning });
